INSERT INTO public."Permission"(id,code,description) VALUES(gen_random_uuid(),'partner.provision.manage','Create or reuse an existing user membership in an existing partner company') ON CONFLICT(code) DO NOTHING;
CREATE TABLE public.partner_membership_provision_operations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id UUID NOT NULL REFERENCES public."User"(id),authority_company_id UUID NOT NULL REFERENCES public."Company"(id),operation_key TEXT NOT NULL CHECK(length(btrim(operation_key)) BETWEEN 1 AND 128),target_user_id UUID NOT NULL REFERENCES public."User"(id),target_company_id UUID NOT NULL REFERENCES public."Company"(id),payload_fingerprint TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('CREATED','ALREADY_EXISTS')),membership_id UUID NOT NULL REFERENCES public."CompanyMembership"(id),created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),UNIQUE(authority_company_id,actor_user_id,operation_key));
ALTER TABLE public.partner_membership_provision_operations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.partner_membership_provision_operations FORCE ROW LEVEL SECURITY; REVOKE ALL ON public.partner_membership_provision_operations FROM PUBLIC,sco_runtime,sco_internal_executor;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='sco_partner_provisioning_gateway_owner') THEN CREATE ROLE sco_partner_provisioning_gateway_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; END IF; END $$;
GRANT USAGE ON SCHEMA public TO sco_partner_provisioning_gateway_owner; GRANT SELECT,INSERT ON public."CompanyMembership" TO sco_partner_provisioning_gateway_owner; GRANT SELECT ON public."User",public."Company",public."MembershipRole",public."RolePermission",public."Permission" TO sco_partner_provisioning_gateway_owner; ALTER TABLE public.partner_membership_provision_operations OWNER TO sco_partner_provisioning_gateway_owner; CREATE POLICY partner_provision_owner ON public.partner_membership_provision_operations FOR ALL TO sco_partner_provisioning_gateway_owner USING(true) WITH CHECK(true);
CREATE FUNCTION public.internal_partner_membership_provision(p_user UUID,p_company UUID,p_key TEXT,p_correlation UUID DEFAULT NULL) RETURNS TABLE(operation_id UUID,membership_id UUID,user_id UUID,company_id UUID,membership_status TEXT,outcome TEXT) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE a UUID; ac UUID; m UUID; o TEXT; f TEXT; e record; BEGIN IF session_user<>'sco_internal_executor' THEN RAISE EXCEPTION 'PARTNER_PROVISION_FORBIDDEN'; END IF; BEGIN a:=NULLIF(current_setting('app.actor_id',true),'')::UUID; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'PARTNER_PROVISION_FORBIDDEN'; END; SELECT cm."companyId" INTO ac FROM public."CompanyMembership" cm JOIN public."Company" c ON c.id=cm."companyId" JOIN public."MembershipRole" mr ON mr.membership_id=cm.id JOIN public."RolePermission" rp ON rp.role_id=mr.role_id JOIN public."Permission" p ON p.id=rp.permission_id JOIN public."User" u ON u.id=cm."userId" WHERE cm."userId"=a AND cm.status='ACTIVE' AND u.status='ACTIVE' AND c.type='SCO' AND c.status='ACTIVE' AND p.code='partner.provision.manage'; IF ac IS NULL OR NOT EXISTS(SELECT 1 FROM public."User" WHERE id=p_user AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."Company" WHERE id=p_company AND status='ACTIVE' AND type='PARTNER') THEN RAISE EXCEPTION 'PARTNER_PROVISION_FORBIDDEN'; END IF; f:=md5(p_user::text||'|'||p_company::text); SELECT * INTO e FROM public.partner_membership_provision_operations WHERE authority_company_id=ac AND actor_user_id=a AND operation_key=btrim(p_key) FOR UPDATE; IF FOUND THEN IF e.target_user_id<>p_user OR e.target_company_id<>p_company OR e.payload_fingerprint<>f THEN RAISE EXCEPTION 'PARTNER_PROVISION_IDEMPOTENCY_CONFLICT'; END IF; RETURN QUERY SELECT e.id,e.membership_id,e.target_user_id,e.target_company_id,'ACTIVE'::TEXT,'REPLAYED'::TEXT; RETURN; END IF; INSERT INTO public."CompanyMembership"("userId","companyId",status) VALUES(p_user,p_company,'ACTIVE') ON CONFLICT("userId","companyId") DO NOTHING RETURNING id INTO m; IF m IS NULL THEN SELECT id INTO m FROM public."CompanyMembership" WHERE "userId"=p_user AND "companyId"=p_company; o:='ALREADY_EXISTS'; ELSE o:='CREATED'; END IF; INSERT INTO public.partner_membership_provision_operations(actor_user_id,authority_company_id,operation_key,target_user_id,target_company_id,payload_fingerprint,outcome,membership_id) VALUES(a,ac,btrim(p_key),p_user,p_company,f,o,m) RETURNING id INTO operation_id; RETURN QUERY SELECT operation_id,m,p_user,p_company,'ACTIVE'::TEXT,o; END $$;
ALTER FUNCTION public.internal_partner_membership_provision(UUID,UUID,TEXT,UUID) OWNER TO sco_partner_provisioning_gateway_owner; REVOKE ALL ON FUNCTION public.internal_partner_membership_provision(UUID,UUID,TEXT,UUID) FROM PUBLIC,sco_runtime; GRANT EXECUTE ON FUNCTION public.internal_partner_membership_provision(UUID,UUID,TEXT,UUID) TO sco_internal_executor;
GRANT INSERT ON public.audit_logs TO sco_partner_provisioning_gateway_owner;
CREATE POLICY partner_provision_audit_insert ON public.audit_logs FOR INSERT TO sco_partner_provisioning_gateway_owner WITH CHECK (scope='SCO_INTERNAL');
CREATE FUNCTION public.partner_membership_provision_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata) VALUES(NEW.actor_user_id,'SCO_INTERNAL','partner.membership.provisioned','CompanyMembership',NEW.membership_id,jsonb_build_object('targetUserId',NEW.target_user_id,'targetCompanyId',NEW.target_company_id,'operationKey',NEW.operation_key,'outcome',NEW.outcome)); RETURN NEW; END $$;
ALTER FUNCTION public.partner_membership_provision_audit() OWNER TO sco_partner_provisioning_gateway_owner;
CREATE TRIGGER partner_membership_provision_audit_after_insert AFTER INSERT ON public.partner_membership_provision_operations FOR EACH ROW EXECUTE FUNCTION public.partner_membership_provision_audit();
